from openpyxl import load_workbook

path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']

sample_cells=['H12','H19','H26','H35','H42','H45','H46','H47','H50']
print('--- Sample formulas ---')
for addr in sample_cells:
    v=ws[addr].value
    print(addr, '=>', v)

# Confirm no cells in target ranges are None/empty
ranges = [
    ('H12','L17'),
    ('H19','L24'),
    ('H26','L31'),
    ('H35','L40'),
    ('H42','L47'),
    ('H50','L50'),
]

def iter_range(start, end):
    for row in ws[start:end]:
        for cell in row:
            yield cell

print('\n--- Missing/empty check ---')
all_ok=True
for start,end in ranges:
    missing=[]
    for cell in iter_range(start,end):
        v=cell.value
        if v is None or (isinstance(v,str) and v.strip()==''):
            missing.append(cell.coordinate)
    if missing:
        all_ok=False
        print(f"Range {start}:{end} missing {len(missing)} cells, e.g.", missing[:10])
    else:
        print(f"Range {start}:{end} OK")

# Confirm formulas start with '='
non_formula=[]
for start,end in ranges:
    for cell in iter_range(start,end):
        v=cell.value
        if not (isinstance(v,str) and v.startswith('=')):
            non_formula.append((cell.coordinate,v))

if non_formula:
    print('\nNon-formula cells found (should all be formulas):', len(non_formula))
    print(non_formula[:15])
else:
    print('\nAll target cells are formula strings starting with =')
